 .Where(c => c.dt_stop_batch >= dtstart && c.dt_stop_batch <= dtstop
 && (cdline == 0 || c.Production_Reg.cd_line == cdline)
 && (cdproduct == 0 || c.Production_Reg.Formula.cd_product == cdproduct))
 .SelectMany(p => p.Production_Batch_Detail_Reg
 .Where(e => e.Weigher.tp_weigher != 11
 && (!enableadditive ? e.Product.tp_product != 11 : true))
 .GroupBy(d => DbFunctions.TruncateTime(p.dt_stop_batch))
 .Select(g => new
