 PsRequested = g.Sum(d => d.nr_production_1 == null ? d.ps_requested : 0) / 1000
 })
 )
 .ToList() 

 //Agrupa os resultados
 var model = lProductionDataDay
 .GroupBy(x => x.Day)
 .Select(g => new ProductionGraphicDay
 {
 Day = g.Key,
 PsDelivered = g.Sum(x => x.PsDelivered),
 PsRequested = g.Sum(x => x.PsRequested),
 Goal = goal,
 PsGoalDiff = goal - Convert.ToDouble(g.Sum(x => x.PsDelivered)),
 NmProduct = cdproduct == 0 ? TODOS : _db.Product.FirstOrDefault(f => f.cd_product == cdproduct).nm_product
 })
